const test = require("node:test");
const assert = require("node:assert");

const { TokenBucket } = require("./limiter");

test("starts full and drains", () => {
  const b = new TokenBucket(3, 1);
  assert.strictEqual(b.allow(0), true);
  assert.strictEqual(b.allow(0), true);
  assert.strictEqual(b.allow(0), true);
  assert.strictEqual(b.allow(0), false);
});

test("refills over time", () => {
  const b = new TokenBucket(3, 1);
  for (let i = 0; i < 3; i++) b.allow(0);
  assert.strictEqual(b.allow(0.5), false);
  assert.strictEqual(b.allow(1.0), true);
  assert.strictEqual(b.allow(1.0), false);
});

test("refill caps at capacity", () => {
  const b = new TokenBucket(2, 1);
  b.allow(0);
  b.allow(0);
  assert.strictEqual(b.allow(1000), true);
  assert.strictEqual(b.allow(1000), true);
  assert.strictEqual(b.allow(1000), false);
});

reference_solution.limiter.js:
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.refillRate = refillRate;
    this.tokens = capacity;
    this.last = null;
  }

  allow(now) {
    if (this.last !== null) {
      const elapsed = now - this.last;
      this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillRate);
    }
    this.last = now;
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }
}

module.exports = { TokenBucket };

